package org.slavicmyths.kalin;
import net.minecraft.commands.Commands;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.RegisterCommandsEvent;import net.neoforged.neoforge.event.entity.living.*;
@EventBusSubscriber(modid="slavicmyths")
public final class KalinEvents {
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){KalinEncounter.get(e.getServer().overworld()).tick(e.getServer().overworld());}
 public static void commands(org.slavicmyths.commands.CommandTree tree){tree.add(Commands.literal("slavicmyths").then(Commands.literal("kalin").then(Commands.literal("challenge").executes(c->KalinEncounter.start(c.getSource().getPlayerOrException())?1:0)).then(Commands.literal("select").then(Commands.argument("hero_a",com.mojang.brigadier.arguments.StringArgumentType.word()).suggests((c,b)->net.minecraft.commands.SharedSuggestionProvider.suggest(KalinEncounter.HEROES,b)).then(Commands.argument("hero_b",com.mojang.brigadier.arguments.StringArgumentType.word()).suggests((c,b)->net.minecraft.commands.SharedSuggestionProvider.suggest(KalinEncounter.HEROES,b)).executes(c->KalinEncounter.select(c.getSource().getPlayerOrException(),com.mojang.brigadier.arguments.StringArgumentType.getString(c,"hero_a"),com.mojang.brigadier.arguments.StringArgumentType.getString(c,"hero_b"))?1:0))))));}
 @SubscribeEvent public static void incoming(LivingIncomingDamageEvent e){var attacker=e.getSource().getEntity();var victim=e.getEntity();var a=attacker==null?null:KalinParty.owner(attacker);var b=KalinParty.owner(victim);if(a!=null&&a.equals(b)&&victim.level() instanceof ServerLevel world&&KalinEncounter.get(world).owner(a)!=null){e.setCanceled(true);return;}if(attacker instanceof KalinEntity k&&(!k.valid()||k.surrendered()||!k.enemy(victim)))e.setCanceled(true);if(attacker instanceof KalinSoldier s&&s.level() instanceof ServerLevel w){var boss=s.commander==null?null:w.getEntity(s.commander);if(!(boss instanceof KalinEntity k)||!k.valid()||k.surrendered()||!k.soldiers.contains(s.getUUID())||!k.enemy(victim))e.setCanceled(true);}}
 @SubscribeEvent public static void damage(LivingDamageEvent.Pre e){if(e.getEntity() instanceof KalinEntity k&&e.getNewDamage()>0){k.damageReceived(e.getSource());if(e.getNewDamage()>=k.getHealth()){e.setNewDamage(0);k.surrender(e.getSource());}}}
 @SubscribeEvent public static void drops(LivingDropsEvent e){if(e.getEntity() instanceof KalinEntity||e.getEntity() instanceof KalinSoldier||e.getEntity() instanceof WarHorse)e.setCanceled(true);}
 @SubscribeEvent public static void xp(LivingExperienceDropEvent e){if(e.getEntity() instanceof KalinEntity||e.getEntity() instanceof KalinSoldier||e.getEntity() instanceof WarHorse)e.setDroppedExperience(0);}
 @SubscribeEvent public static void clone(net.neoforged.neoforge.event.entity.player.PlayerEvent.Clone e){var n=e.getOriginal().getPersistentData();if(n.contains("slavicmyths.kalin175"))e.getEntity().getPersistentData().put("slavicmyths.kalin175",n.getCompound("slavicmyths.kalin175").copy());}
}
